message.content:
{
  "css": ".trip-header {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 62px;
  min-height: 62px;
  position: relative;
}

.trip-header > button {
  position: absolute;
  left: 0;
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  padding: 0;
  cursor: default;
}

.trip-header > button[disabled] {
  opacity: 1;
}

.trip-header > button img {
  width: 24px;
  height: 24px;
  display: block;
  pointer-events: none;
}

.trip-header > h1 {
  font-size: 18px;
  line-height: 26px;
  font-weight: 700;
  text-align: center;
  margin: 0;
  padding: 0 44px;
  white-space: normal;
  overflow-wrap: break-word;
  word-break: keep-all;
  color: var(--ink, #111);
}

.trip-header > span {
  position: absolute;
  right: 0;
  width: 44px;
  height: 44px;
  pointer-events: none;
}"
}
